def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n or (i == n and not fields):
        if i >= n:
            # Empty field at end (after a comma)
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that it's followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        # Skip the comma if present
                        if i < n and line[i] == ',':
                            i += 1
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Skip the comma if present
            if i < n and line[i] == ',':
                i += 1

    return fields

